# Databricks notebook source
# MAGIC %md
# MAGIC # 05 Sync workbench decisions
# MAGIC
# MAGIC The review workbench records every decision and field correction in Lakebase Postgres (schema
# MAGIC `daw`). This step copies them into Unity Catalog (`silver_workbench_decisions`,
# MAGIC `silver_workbench_corrections`, MERGE on their ids) so step 03 can measure extraction accuracy
# MAGIC from what reviewers changed, and straight-through rate from what they accepted untouched.
# MAGIC
# MAGIC Authentication: a short-lived Lakebase credential generated by the SDK for the job's
# MAGIC identity; nothing is stored. If the workbench has not been deployed yet (no endpoint, or no
# MAGIC tables), the silver tables stay empty and the step exits cleanly. Connection failures are not
# MAGIC swallowed.

# COMMAND ----------

# MAGIC %pip install --quiet "psycopg[binary]>=3.1"

# COMMAND ----------

import datetime as dt
import os
import sys

dbutils.widgets.text("src_dir", "")
_src = dbutils.widgets.get("src_dir").strip()
_found = next((c for c in [_src, os.path.join(_src, "src"), "."] if c and os.path.isfile(os.path.join(c, "common.py"))), None)
if _found is None:
    raise FileNotFoundError("common.py not found - pass src_dir pointing at the use case's src folder")
sys.path.insert(0, _found)

import pandas as pd  # noqa: E402

from common import fq, get_params  # noqa: E402

p = get_params({"catalog": "", "schema": "", "lakebase_project_id": "", "lakebase_branch_id": "production",
                "lakebase_endpoint_id": "primary"}, dbutils)
CATALOG, SCHEMA = p["catalog"], p["schema"]
PROJECT, BRANCH, ENDPOINT = p["lakebase_project_id"], p["lakebase_branch_id"], p["lakebase_endpoint_id"]
DATABASE = "databricks_postgres"
t = lambda name: fq(CATALOG, SCHEMA, name)  # noqa: E731

DECISIONS_DDL = ("decision_id STRING, doc_id STRING, decision STRING, reason_codes STRING, note STRING, doc_type STRING, "
                 "status_seen STRING, lowest_confidence_seen DOUBLE, fields_corrected INT, handling_seconds INT, "
                 "decided_by STRING, decided_at TIMESTAMP, synced_at TIMESTAMP")
CORRECTIONS_DDL = ("correction_id STRING, doc_id STRING, field STRING, extracted_value STRING, corrected_value STRING, "
                   "routing_confidence DOUBLE, corrected_by STRING, corrected_at TIMESTAMP, synced_at TIMESTAMP")
for name, ddl, comment in [
    ("silver_workbench_decisions", DECISIONS_DDL, "Reviewer decisions copied from the workbench (Lakebase daw.document_decision). One final decision per document."),
    ("silver_workbench_corrections", CORRECTIONS_DDL, "Field corrections copied from the workbench (Lakebase daw.field_correction): what the reviewer changed, and the value extracted."),
]:
    spark.sql(f"CREATE TABLE IF NOT EXISTS {t(name)} ({ddl}) COMMENT '{comment}'")

# COMMAND ----------

def read_lakebase():
    """(decisions, corrections) DataFrames, or (None, None, reason) when there is nothing to read yet."""
    if not PROJECT:
        return None, None, "no lakebase_project_id"
    import psycopg
    from databricks.sdk import WorkspaceClient
    from databricks.sdk.errors import NotFound

    w = WorkspaceClient()
    endpoint_name = f"projects/{PROJECT}/branches/{BRANCH}/endpoints/{ENDPOINT}"
    try:
        endpoint = w.postgres.get_endpoint(name=endpoint_name)
    except NotFound:
        return None, None, f"Lakebase endpoint {endpoint_name} not found; workbench not deployed yet"
    host = getattr(getattr(getattr(endpoint, "status", None), "hosts", None), "host", None)
    if not host:
        raise RuntimeError(f"could not resolve a host for {endpoint_name}")
    token = w.postgres.generate_database_credential(endpoint=endpoint_name).token
    user = w.current_user.me().user_name
    with psycopg.connect(host=host, port=5432, dbname=DATABASE, user=user, password=token, sslmode="require", connect_timeout=30) as conn:
        if conn.execute("SELECT to_regclass('daw.document_decision')").fetchone()[0] is None:
            return None, None, "daw.document_decision does not exist yet"
        d = conn.execute("""SELECT decision_id::text, doc_id, decision, array_to_string(reason_codes, ','), note, doc_type, status_seen,
                                   lowest_confidence_seen, fields_corrected, handling_seconds, decided_by, decided_at
                            FROM daw.document_decision""").fetchall()
        c = conn.execute("""SELECT correction_id::text, doc_id, field, extracted_value, corrected_value, routing_confidence,
                                   corrected_by, corrected_at FROM daw.field_correction""").fetchall()
    dcols = [x.split()[0] for x in DECISIONS_DDL.split(", ")][:-1]
    ccols = [x.split()[0] for x in CORRECTIONS_DDL.split(", ")][:-1]
    return pd.DataFrame(d, columns=dcols), pd.DataFrame(c, columns=ccols), None


decisions, corrections, reason = read_lakebase()
if reason:
    dbutils.notebook.exit(f"No workbench decisions read: {reason}")

now = dt.datetime.utcnow()
for frame, name, ddl, key, ts in [(decisions, "silver_workbench_decisions", DECISIONS_DDL, "decision_id", "decided_at"),
                                  (corrections, "silver_workbench_corrections", CORRECTIONS_DDL, "correction_id", "corrected_at")]:
    if frame is None or not len(frame):
        continue
    frame = frame.copy()
    frame[ts] = pd.to_datetime(frame[ts], utc=True).dt.tz_convert(None)
    frame["synced_at"] = now
    spark.createDataFrame(frame.astype(object).where(pd.notna(frame), None), ddl).createOrReplaceTempView("stage")
    spark.sql(f"MERGE INTO {t(name)} AS tgt USING stage AS src ON tgt.{key} = src.{key} "
              "WHEN MATCHED THEN UPDATE SET * WHEN NOT MATCHED THEN INSERT *")
    print(f"merged {len(frame)} rows into {name}")
